const seriesDDC = `-- name: SeriesDDC :one
SELECT e.ddc, count(*) AS n
FROM editions e JOIN works w ON w.id = e.work_id JOIN series s ON s.id = w.series_id
WHERE s.name = ? AND e.ddc <> ''
GROUP BY e.ddc
ORDER BY n DESC
LIMIT 1
`

type SeriesDDCRow struct {
	Ddc string
	N   int64
}

// The number most of a series already has, for a volume no source has catalogued yet.
func (q *Queries) SeriesDDC(ctx context.Context, name string) (*SeriesDDCRow, error) {
	row := q.db.QueryRowContext(ctx, seriesDDC, name)
	var i SeriesDDCRow
	err := row.Scan(&i.Ddc, &i.N)
	return &i, err
}

